:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --primary: #6c5ce7;
  --primary-hover: #7f6ff0;
  --primary-active: #5a4bd1;
  --accent: #00cec9;
  --danger: #ff7675;
  --success: #55efc4;
  --border: #3d3d5c;
  --focus: #fdcb6e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 2rem;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  border: 1px solid var(--border);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
  color: var(--accent);
}

.subtitle {
  margin-bottom: 1.5rem;
  opacity: 0.8;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
  color: var(--primary);
}

h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
  opacity: 0.9;
}

section {
  margin-bottom: 2rem;
}

.form-group {
  margin-bottom: 1rem;
}

label {
  display: block;
  margin-bottom: 0.25rem;
  font-weight: 500;
}

input, select {
  width: 100%;
  padding: 0.6rem 0.75rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:hover, select:hover {
  border-color: var(--primary);
}

input:focus, select:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(253, 203, 110, 0.3);
}

.btn {
  display: inline-block;
  padding: 0.65rem 1.5rem;
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: var(--primary-hover);
}

.btn:active {
  background: var(--primary-active);
  transform: scale(0.98);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.expenses {
  list-style: none;
}

.expenses li {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--border);
}

.expenses li:last-child {
  border-bottom: none;
}

.empty {
  opacity: 0.6;
  font-style: italic;
}

.totals-list, .settlement-list {
  list-style: none;
}

.totals-list li, .settlement-list li {
  display: flex;
  justify-content: space-between;
  padding: 0.4rem 0;
}

.positive {
  color: var(--success);
}

.negative {
  color: var(--danger);
}

.neutral {
  color: var(--text);
  opacity: 0.7;
}

@media (max-width: 480px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
}

const friends = ['Alice', 'Bob', 'Charlie'];
let expenses = [];

const form = document.getElementById('expense-form');
const payerSelect = document.getElementById('payer');
const amountInput = document.getElementById('amount');
const descriptionInput = document.getElementById('description');
const expensesList = document.getElementById('expenses');
const emptyMessage = document.getElementById('empty-message');
const totalsList = document.getElementById('totals-list');
const settlementList = document.getElementById('settlement-list');

function render() {
  // Render expense list
  expensesList.innerHTML = '';
  if (expenses.length === 0) {
    emptyMessage.style.display = 'block';
  } else {
    emptyMessage.style.display = 'none';
    expenses.forEach(exp => {
      const li = document.createElement('li');
      const desc = exp.description ? ` – ${exp.description}` : '';
      li.innerHTML = `<span>${exp.payer}${desc}</span><span>$${exp.amount.toFixed(2)}</span>`;
      expensesList.appendChild(li);
    });
  }

  // Calculate totals
  const totals = {};
  friends.forEach(f => totals[f] = 0);
  expenses.forEach(exp => {
    totals[exp.payer] += exp.amount;
  });

  // Render totals
  totalsList.innerHTML = '';
  friends.forEach(f => {
    const li = document.createElement('li');
    li.innerHTML = `<span>${f}</span><span>$${totals[f].toFixed(2)}</span>`;
    totalsList.appendChild(li);
  });

  // Calculate settlement
  const totalSpent = Object.values(totals).reduce((a, b) => a + b, 0);
  const fairShare = totalSpent / friends.length;

  const balances = friends.map(f => ({
    name: f,
    balance: totals[f] - fairShare
  }));

  // Render settlement
  settlementList.innerHTML = '';
  balances.forEach(b => {
    const li = document.createElement('li');
    const amount = Math.abs(b.balance).toFixed(2);
    let text, cls;
    if (b.balance > 0.005) {
      text = `${b.name} is owed $${amount}`;
      cls = 'positive';
    } else if (b.balance < -0.005) {
      text = `${b.name} owes $${amount}`;
      cls = 'negative';
    } else {
      text = `${b.name} is settled up`;
      cls = 'neutral';
    }
    li.innerHTML = `<span>${text}</span>`;
    li.className = cls;
    settlementList.appendChild(li);
  });
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const payer = payerSelect.value;
  const amount = parseFloat(amountInput.value);
  const description = descriptionInput.value.trim();

  if (!payer || isNaN(amount) || amount <= 0) {
    alert('Please enter a valid amount greater than 0.');
    return;
  }

  expenses.push({ payer, amount, description });
  form.reset();
  payerSelect.focus();
  render();
});

// Initial render
render();
